cd /gin && cat > /tmp/ci_test.go <<'EOF'
package gin

import (
	"fmt"
	"testing"
)

func TestCIMulti(t *testing.T) {
	tree := &node{}
	routes := []string{"/:id/foo", "/static"}
	for _, r := range routes {
		tree.addRoute(r, fakeHandler(r))
	}
	for _, p := range []string{"/STATIC", "/:ID/FOO", "/AbC/FoO"} {
		func() {
			defer func() {
				if e := recover(); e != nil {
					fmt.Println("PANIC for", p, ":", e)
				}
			}()
			out, found := tree.findCaseInsensitivePath(p, true)
			fmt.Printf("in=%q out=%q found=%v\n", p, string(out), found)
		}()
	}
}
EOF
cp /tmp/ci_test.go /gin/ci_test.go && go test -run TestCIMulti -v . 2>&1 | head -30

